/**
 * Colours and marks, all generated by `make brand` (scripts/brand-sync.py)
 * into ../brand/: tokens.json (the Agentization Core design tokens, by role),
 * mark.json and chips.json (the AC wordmark and a-c mark, sampled from their
 * generated SVGs onto braille dots — never traced from a raster).
 * A missing or unreadable file degrades to text — never breaks the TUI.
 */
import { readJson } from "./env.ts";

export type Run = [string | null, string];
export type Variant = { cols: number; rows: Run[][] };
export type Mark = { palette: Record<string, string>; full: Variant; compact: Variant };
export type Chip = { size: string; cols: number; rows: number; lines: Run[][] };

const brand = (name: string) => new URL(`../brand/${name}`, import.meta.url);

const tokens = readJson<{ colors: Record<string, string>; wordmark?: { en: string } }>(brand("tokens.json"));
const t = tokens?.colors ?? {};

export const C = {
  accent: t["accent"] ?? "#ffffff",
  accentBright: t["accentBright"] ?? "#f5f5f5",
  text: t["text"] ?? "#d4d4d4",
  muted: t["muted"] ?? "#8a8a8a",
  brand: t["brand"] ?? "#878787",
  white: t["white"] ?? "#ffffff",
  bg: t["bg"] ?? "#000000",
  panel: t["bgPanel"] ?? "#0a0a0a",
  element: t["bgElement"] ?? "#141414",
  border: t["border"] ?? "#2e2e2e",
  red: t["red"] ?? "#ef4444",
  green: t["green"] ?? "#0ca30c",
  blue: t["blue"] ?? "#6fa8ff",
  yellow: t["yellow"] ?? "#fab219",
};

export const WORDMARK = tokens?.wordmark?.en ?? "agentization-core";
export const MARK = readJson<Mark>(brand("mark.json"));
/** Smallest first. */
export const CHIPS: Chip[] = (readJson<{ sizes: Chip[] }>(brand("chips.json"))?.sizes ?? [])
  .slice().sort((a, b) => a.cols * a.rows - b.cols * b.rows);

export const BOLD = 1;
